import { db } from "@/lib/db";
import { REVENUE_USER_WHERE } from "@/lib/admin-metrics";

/**
 * Account-level retention: of the people who created a Nxeon account, how many
 * come back and do anything at all afterward?
 *
 * There is no `lastLoginAt` on `User`, and the marketing visit tracker
 * (`VisitTracker`, app/(marketing)/layout.tsx) only fires on marketing pages —
 * NOT inside the portal — so `Visit.userId` alone would undercount real
 * product usage. Instead this unions every timestamped, userId-owned action
 * across the tables that represent someone actually doing something on the
 * platform: a marketing pageview while signed in, a wallet transaction, a
 * server, a ticket, a project, an invoice, a hosting account, or an
 * audit-logged action. If ANY of those happened after the signup-day cutoff,
 * the account "returned".
 *
 * Scoped to `REVENUE_USER_WHERE` (excludeFromRevenue: false) + non-admin, the
 * same "real customer" filter already used for revenue/MRR — see
 * lib/admin-metrics.ts. Staff/sandbox/e2e-test accounts are excluded there;
 * an operator's own personal test accounts are NOT automatically caught by
 * that flag unless someone remembered to set it (see the account's own
 * `/admin/users/[id]` toggle) — this view can't tell the difference, so a
 * skewed number here is often itself the signal that a test account needs
 * flagging, not that retention is unusually good.
 */

const DAY_MS = 86_400_000;

export type RetentionAccount = {
  id: string;
  email: string;
  name: string;
  signup: Date;
  lastActivity: Date | null;
  daysSinceSignup: number;
  returned1d: boolean;
  returned7d: boolean;
  returned30d: boolean;
};

export type RetentionSummary = {
  total: number;
  eligible1d: number;
  returned1d: number;
  eligible7d: number;
  returned7d: number;
  eligible30d: number;
  returned30d: number;
};

/** Merge a groupBy-by-userId `_max.createdAt` result into the running best-seen map. */
function mergeMax(into: Map<string, Date>, rows: { userId: string | null; _max: { createdAt: Date | null } }[]) {
  for (const r of rows) {
    if (!r.userId || !r._max.createdAt) continue;
    const prev = into.get(r.userId);
    if (!prev || r._max.createdAt > prev) into.set(r.userId, r._max.createdAt);
  }
}

/** Per-account signup + last-activity rows for every real-customer account. */
