    db.visit.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _max: { createdAt: true } }),
    db.walletTransaction.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _max: { createdAt: true } }),
    db.server.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _max: { createdAt: true } }),
    db.ticket.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _max: { createdAt: true } }),
    db.project.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _max: { createdAt: true } }),
    db.invoice.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _max: { createdAt: true } }),
    db.hostingAccount.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _max: { createdAt: true } }),
    db.auditLog.groupBy({ by: ["userId"], where: { userId: { in: ids } }, _max: { createdAt: true } }),
  ]);

  const lastActivity = new Map<string, Date>();
  mergeMax(lastActivity, visits);
  mergeMax(lastActivity, wallet);
  mergeMax(lastActivity, servers);
  mergeMax(lastActivity, tickets);
  mergeMax(lastActivity, projects);
  mergeMax(lastActivity, invoices);
  mergeMax(lastActivity, hosting);
  mergeMax(lastActivity, audit);

