import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";
import {
  isRevenueDescription,
  NON_REVENUE_PREFIXES,
  REVENUE_WHERE,
  ADMIN_CREDIT_WHERE,
  serverMonthlyCents,
  fleetMrrCents,
  monthlyCents,
  type MrrServer,
} from "../lib/admin-metrics.ts";

/**
 * The figures the admin console puts in front of an operator must be computed
 * from what they claim to measure. `lib/admin-metrics.ts` is the single source of
 * truth for that arithmetic; every one of its helpers exists because a headline
 * number was previously wrong in the flattering direction (a refund read as
 * revenue, a game server priced at the base VPS rate, a suspended machine billed
 * forever).
 *
 * The helper module was written and wired into the overview, but three financial
 * pages — /admin/billing, /admin/subscriptions, /admin/analytics — kept the exact
 * naive math the module's own docstrings name as the defect. These tests do two
 * jobs: prove the pure arithmetic, and PIN every financial surface to the helper
 * so a page cannot quietly drift back to `SUM(amountCents < 0)` for revenue or
 * `SUM(plan.priceCents)` for MRR.
 *
 * Source is stripped of comments/strings before any structural assertion — this
 * repo documents its incidents in the code, and a naive grep matches the incident
 * note and passes on broken code. See test/_source-tools.ts.
 */

const ROOT = join(import.meta.dirname, "..");

function code(rel: string): string {
  return stripCommentsAndStrings(readFileSync(join(ROOT, rel), "utf8"));
}

/* ================================================================== *
 * 1. Revenue classification — the pure rule
 * ================================================================== */

test("every reversal prefix classifies as NON-revenue", () => {
  for (const prefix of NON_REVENUE_PREFIXES) {
    assert.equal(
      isRevenueDescription(`${prefix} — whatever follows`),
      false,
      `a ledger row starting "${prefix}" is money leaving the business, not revenue`,
    );
  }
});

test("genuine earned-income descriptions classify as revenue", () => {
  // The exact static prefixes of the debit rows the billing engine writes when a
  // customer actually pays for something.
  for (const desc of [

  for (const desc of [
    "Order: Pro VPS (web-01) — 12 months",
    "Renewal: Pro VPS (web-01) — 12 months",
    "Stripe payment (cs_test_123)",
    "Game server: Valheim (VALHEIM)",
    "Domain registration: example.com (1 year)",
    "Business Email: Standard for example.com",
    "Block storage volume: data (50 GB)",
    "Upgrade to Pro (prorated) — web-01",
  ]) {
    assert.equal(isRevenueDescription(desc), true, `"${desc}" is earned revenue`);
  }
});

test("REVENUE_WHERE selects debits and excludes every reversal prefix", () => {
  // Structural: a debit filter whose NOT-list is exactly the reversal prefixes.
  assert.deepEqual(REVENUE_WHERE.amountCents, { lt: 0 });
  const notList = REVENUE_WHERE.NOT as { description: { startsWith: string } }[];
  assert.deepEqual(
    notList.map((n) => n.description.startsWith).sort(),
    [...NON_REVENUE_PREFIXES].sort(),
    "REVENUE_WHERE must exclude precisely the reversal prefixes it documents",
  );
});

test("ADMIN_CREDIT_WHERE matches BOTH admin credit tools", () => {
  const or = ADMIN_CREDIT_WHERE.OR as { description: { startsWith: string } }[];
  const prefixes = or.map((o) => o.description.startsWith);
  // adminCreditUser writes "Admin credit adjustment"; adjustBalance (rendered on
  // the billing page itself) writes "Admin balance adjustment". Miss either and
  // the "Credits issued" figure under-reports the page's own actions.
  assert.ok(prefixes.some((p) => "Admin credit adjustment".startsWith(p)));
  assert.ok(prefixes.some((p) => "Admin balance adjustment".startsWith(p)));
});

/* ================================================================== *
 * 2. Classification stays grounded in the real ledger rows
 * ================================================================== *
 * Every prefix in NON_REVENUE_PREFIXES must correspond to a NEGATIVE (or
 * zero-value) walletTransaction actually written somewhere — otherwise the list
 * is decoration. And, the mirror: the known reversal WRITERS must each carry a
 * classified prefix. This is what fails when a new negative ledger row is added
 * with a description nobody classified.
 */

/** Source of the modules that write wallet ledger rows (comments removed only). */
function ledgerSources(): string {
  const dirs = ["lib", "worker"];
  let all = "";
  for (const d of dirs) {
    for (const f of readdirSync(join(ROOT, d))) {
      if (f.endsWith(".ts")) all += "\n" + stripComments(readFileSync(join(ROOT, d, f), "utf8"));
    }
  }
  return all;
}

test("every NON_REVENUE_PREFIX names a ledger row that really exists", () => {
  const src = ledgerSources();
  for (const prefix of NON_REVENUE_PREFIXES) {
    // The description literal is written as "<prefix> …" or `<prefix> …`.
    const present = src.includes(`"${prefix}`) || src.includes(`\`${prefix}`);
    assert.ok(
      present,
      `NON_REVENUE_PREFIXES lists "${prefix}" but no ledger row is written with it — ` +
        `remove the dead prefix or restore its writer`,
    );
  }
});

test("the known reversal writers are all classified non-revenue", () => {
  // These five NEGATIVE (or zero) rows are the ones that would inflate revenue if
  // counted. Each must be caught by the classifier. If a refactor renames one, the
  // string here and NON_REVENUE_PREFIXES must move together.
  const REVERSALS = [
    "Refund — Stripe refund re_x · invoice INV-1",
    "Write-off — $5.00 of this refund was returned to the card",
    "Admin balance adjustment — clawback",
    "Affiliate payout request (wallet cash-out)",
    "Reversed downgrade credit (resize failed) — web-01",
  ];
  for (const d of REVERSALS) {
    assert.equal(isRevenueDescription(d), false, `"${d}" must not count as revenue`);
  }
});

/* ================================================================== *
 * 3. MRR arithmetic
 * ================================================================== */

const vps = (over: Partial<MrrServer> = {}): MrrServer => ({
  status: "RUNNING",
  isFree: false,
  termMonths: 1,
  plan: { priceCents: 1000 },
  gamePlan: null,
  ...over,
});

test("free / suspended / deleting servers contribute nothing to MRR", () => {
  assert.equal(serverMonthlyCents(vps({ isFree: true })), 0);
  assert.equal(serverMonthlyCents(vps({ status: "SUSPENDED" })), 0);
  assert.equal(serverMonthlyCents(vps({ status: "DELETING" })), 0);
});

test("a term price is normalised to a month", () => {
  // A 36-month plan at $360 list is $10/mo committed, not $360.
  assert.equal(monthlyCents(36000, 36), 1000);
  assert.equal(serverMonthlyCents(vps({ termMonths: 36, plan: { priceCents: 36000 } })), 1000);
});

test("a game server is priced at its game plan, not the base VPS plan", () => {
  // Base plan $8.99, game plan $4.99/mo flat: MRR must read the game plan.
  const s = vps({ plan: { priceCents: 899 }, gamePlan: { priceCents: 499, termMonths: 1 } });
  assert.equal(serverMonthlyCents(s), 499);
});

test("fleetMrrCents sums per-server monthly contributions", () => {
  const fleet = [
    vps({ plan: { priceCents: 1000 } }),
    vps({ isFree: true }),
    vps({ status: "SUSPENDED", plan: { priceCents: 9999 } }),
    vps({ plan: { priceCents: 899 }, gamePlan: { priceCents: 499, termMonths: 1 } }),
  ];
  assert.equal(fleetMrrCents(fleet), 1000 + 0 + 0 + 499);
});

/* ================================================================== *
 * 4. Every financial surface uses the helpers (bites on a revert)
 * ================================================================== */

const REVENUE_PAGES = [
  "app/admin/page.tsx",
  "app/admin/billing/page.tsx",
  "app/admin/subscriptions/page.tsx",
  "app/admin/analytics/page.tsx",
] as const;

test("every page that shows revenue derives it from REVENUE_WHERE", () => {
  for (const page of REVENUE_PAGES) {
    const src = code(page);
    assert.ok(
      src.includes("REVENUE_WHERE"),
      `${page} shows revenue but does not use REVENUE_WHERE — a bare amountCents<0 sum ` +
        `counts refunds and affiliate cash-outs as revenue`,
    );
  }
});

test("every page that shows MRR derives it from serverMonthlyCents / fleetMrrCents", () => {
  // These three surface an MRR figure; each must price it through the helper so
  // game plans, term proration and suspended machines are handled — never a raw
  // sum of plan.priceCents.
  for (const page of ["app/admin/page.tsx", "app/admin/subscriptions/page.tsx", "app/admin/analytics/page.tsx"]) {
    const src = code(page);
    assert.ok(
      src.includes("fleetMrrCents") || src.includes("serverMonthlyCents"),
      `${page} shows MRR but does not use the pricing helper`,
    );
  }
});

test("billing 'Credits issued' uses ADMIN_CREDIT_WHERE (both credit tools)", () => {
  const src = code("app/admin/billing/page.tsx");
  assert.ok(
    src.includes("ADMIN_CREDIT_WHERE"),
    "billing page must classify admin credits via ADMIN_CREDIT_WHERE, not a single description match",
  );
});

/* ================================================================== *
 * 5. Status dots are derived, never hardcoded
 * ================================================================== *
 * The automation page asserts, in prose, that it shows "no vapourware". Its four
 * subsystem dots were literal `status="online"` regardless of whether the worker
 * was running. A StatusDot whose `status` is a STRING LITERAL is a hardcoded
 * claim; a healthy one reads its state from a signal via `status={…}`. (String
 * CONTENTS are blanked by the stripper, but the opening quote of a literal
 * attribute survives — `status="` — while an expression is `status={`.)
 */
test("the automation page derives every status dot from a real signal", () => {
  const src = code("app/admin/automation/page.tsx");
  assert.ok(src.includes("workerHealth("), "worker/billing/forward dots must read workerHealth()");
  assert.equal(
    /StatusDot\s+status="/.test(src),
    false,
    "a StatusDot with a string-literal status on the automation page is a hardcoded liveness claim — " +
      "drive it from a health signal via status={…}",
  );
});

/* ================================================================== *
 * 6. Headline totals are counted over the whole table, not a capped page
 * ================================================================== *
 * Several pages load a `take:N`-capped list for display and used to derive their
 * stat-card totals from that same capped array — so "Total codes", "Outstanding
 * value", "Total paid out" and the chat totals silently under-reported once the
 * table exceeded the cap. Each total must come from a DB count()/aggregate().
 */
/* ================================================================== *
 * 7. Every abuse-queue write is attributable
 * ================================================================== *
 * suspendForAbuse always wrote an AuditLog row; its siblings acknowledge/resolve
 * closed cases with no record of who did it. All three now audit. The action-name
 * literal is the proxy — it appears only in the auditLog.create for that action,
 * so removing the audit removes the literal. (stripComments keeps strings.)
 */
test("every abuse-queue write records who did it", () => {
  const src = stripComments(readFileSync(join(ROOT, "lib/actions-abuse.ts"), "utf8"));
  for (const action of ["abuse.acknowledge", "abuse.resolve", "abuse.suspend"]) {
    assert.ok(
      src.includes(`"${action}"`),
      `${action} must write an AuditLog row so the action is attributable`,
    );
  }
});

test("capped-list pages count their headline totals over the whole table", () => {
  const cases: [string, string[]][] = [
    ["app/admin/chat/page.tsx", ["chatConversation.count("]],
    ["app/admin/gift-codes/page.tsx", ["giftCode.count(", "giftCode.aggregate("]],
    ["app/admin/affiliate/page.tsx", ["affiliatePayout.count(", "affiliatePayout.aggregate("]],
  ];
  for (const [page, needles] of cases) {
    const src = code(page);
    for (const n of needles) {
      assert.ok(
        src.includes(n),
        `${page} shows a headline total but does not compute it with ${n} — a value derived from the ` +
          `take:N display list under-reports past the cap`,
      );
    }
  }
});

