1	// Affiliate program logic — tier constants + earnings/payout computation.
2	//
3	// Plain (non-"use server") module: exports constants and (db-backed) computation
4	// helpers used by the affiliate pages and server actions. Not for client import.
5	//
6	// Accounting model (revised — fixes the affiliate double-pay)
7	// -----------------------------------------------------------
8	// The existing referral engine (lib/actions-growth.ts → maybeRewardReferral)
9	// already credits a referrer's WALLET when a person they referred makes their
10	// first payment, writing a ledger row with the description below. Because that
11	// money is ALREADY spendable in the wallet, an affiliate "payout" must not mint
12	// new money — it CONVERTS existing wallet credit into a cash-out request:
13	//
14	//   * request payout  -> DEBIT the wallet now, create AffiliatePayout(PENDING)
15	//   * admin PAID       -> just mark paid (the money already left the wallet)
16	//   * admin DECLINED   -> CREDIT the wallet back (cash-out cancelled)
17	//
18	// `totalEarned` (the referral ledger sum) stays the lifetime-commission headline,
19	// but "available to cash out" is now capped by the ACTUAL wallet balance so a
20	// customer can't both spend their referral credit on servers AND cash it out
21	// (the old bug: earnings were counted as separately cashable on top of the wallet).
22	//
23	// available = clamp(0, min(walletBalance, totalEarned − PENDING − APPROVED − PAID))
24	
25	import { db } from "./db";
26	
27	/** Exact WalletTransaction.description written for the referrer's reward (see
28	 *  lib/actions-growth.ts). Used to total affiliate earnings from the ledger. */
29	export const REFERRAL_EARNING_DESCRIPTION = "Referral bonus — you referred a friend";
30	
31	/** Minimum balance (cents) a customer must have available to request a payout. */
32	export const MIN_PAYOUT_CENTS = 2500; // $25.00
33	
34	/** Payout lifecycle statuses (mirrors AffiliatePayout.status). */
35	export const PAYOUT_STATUSES = ["PENDING", "APPROVED", "PAID", "DECLINED"] as const;
36	export type PayoutStatus = (typeof PAYOUT_STATUSES)[number];
37	
38	/**
39	 * Commission tiers. `perReferralCents` is what the marketing copy advertises a
40	 * paying referral is worth once you reach `minReferrals` paying referrals — an
41	 * escalating incentive. (The wallet credit actually paid per referral is governed
42	 * by the `referral_reward_cents` Setting / REFERRAL_REWARD_CENTS in the growth
43	 * engine; these tiers are the customer-facing program description.)
44	 */
45	export const AFFILIATE_TIERS = [
46	  { name: "Starter", minReferrals: 0, perReferralCents: 500 },
47	  { name: "Pro", minReferrals: 5, perReferralCents: 800 },
48	  { name: "Elite", minReferrals: 15, perReferralCents: 1200 },
49	] as const;
50	
51	export type AffiliateTier = (typeof AFFILIATE_TIERS)[number];
52	
53	/** The tier a customer currently sits in given their paying-referral count. */
54	export function currentTier(payingReferrals: number): AffiliateTier {
55	  let tier: AffiliateTier = AFFILIATE_TIERS[0];
56	  for (const t of AFFILIATE_TIERS) {
57	    if (payingReferrals >= t.minReferrals) tier = t;
58	  }
59	  return tier;
60	}
61	
62	/** The next tier up (null if already at the top), for "N more to unlock…" copy. */
63	export function nextTier(payingReferrals: number): AffiliateTier | null {
64	  return AFFILIATE_TIERS.find((t) => t.minReferrals > payingReferrals) ?? null;
65	}
66	
67	export type AffiliateEarnings = {
68	  referredCount: number;
69	  payingCount: number;
70	  totalEarnedCents: number;
71	  pendingPayoutCents: number; // PENDING + APPROVED (in-flight, not yet cashed out)
72	  paidPayoutCents: number; // PAID
73	  availableCents: number; // totalEarned − (pending + approved + paid)
74	  tier: AffiliateTier;
75	  next: AffiliateTier | null;
76	  canRequestPayout: boolean;
77	};
78	
79	/**
80	 * Compute a customer's affiliate standing: referral counts, lifetime earnings
81	 * (from the wallet ledger) and how much is still available to cash out after
82	 * subtracting non-declined payouts.
83	 */
84	export async function computeAffiliateEarnings(userId: string): Promise<AffiliateEarnings> {
85	  const [referredCount, payingCount, earnedAgg, payouts, account] = await Promise.all([
86	    db.user.count({ where: { referredById: userId } }),
87	    db.user.count({ where: { referredById: userId, referralRewardedAt: { not: null } } }),
88	    db.walletTransaction.aggregate({
89	      _sum: { amountCents: true },
90	      where: { userId, description: REFERRAL_EARNING_DESCRIPTION },
91	    }),
92	    db.affiliatePayout.findMany({
93	      where: { userId, status: { not: "DECLINED" } },
94	      select: { amountCents: true, status: true },
95	    }),
96	    db.user.findUnique({ where: { id: userId }, select: { balanceCents: true } }),
97	  ]);
98	
99	  const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
100	  const walletBalanceCents = account?.balanceCents ?? 0;
101	  let pendingPayoutCents = 0;
102	  let paidPayoutCents = 0;
103	  for (const p of payouts) {
104	    if (p.status === "PAID") paidPayoutCents += p.amountCents;
105	    else pendingPayoutCents += p.amountCents; // PENDING or APPROVED
106	  }
107	
108	  // Referral credit already sits in the wallet; a payout debits the wallet. So the
109	  // cashable amount is the unclaimed referral commission, but never more than the
110	  // customer actually still holds in their wallet (they may have spent some of it).
111	  const unclaimedEarnedCents = Math.max(0, totalEarnedCents - pendingPayoutCents - paidPayoutCents);
112	  const availableCents = Math.max(0, Math.min(walletBalanceCents, unclaimedEarnedCents));
113	
114	  return {
115	    referredCount,
116	    payingCount,
117	    totalEarnedCents,
118	    pendingPayoutCents,
119	    paidPayoutCents,
120	    availableCents,
121	    tier: currentTier(payingCount),
122	    next: nextTier(payingCount),
123	    canRequestPayout: availableCents >= MIN_PAYOUT_CENTS,
124	  };
125	}
