1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser, assertNotImpersonating } from "./auth";
6	import { requireArea } from "./rbac";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { getSettingBool } from "./settings";
9	import {
10	  MIN_PAYOUT_CENTS,
11	  PAYOUT_STATUSES,
12	  REFERRAL_EARNING_DESCRIPTION,
13	  type PayoutStatus,
14	} from "./affiliate";
15	import { emailVerificationError } from "./email-verification";
16	
17	/** Local sentinel: requested payout exceeds the caller's cashable affiliate balance. */
18	class PayoutExceedsAvailableError extends Error {
19	  availableCents: number;
20	  constructor(availableCents: number) {
21	    super("PAYOUT_EXCEEDS_AVAILABLE");
22	    this.name = "PayoutExceedsAvailableError";
23	    this.availableCents = availableCents;
24	  }
25	}
26	
27	// ---------- Customer: request a payout ----------
28	
29	/**
30	 * Request an affiliate payout for `amountCents`. Model: referral rewards already
31	 * live in the wallet, so a payout CONVERTS wallet credit into a cash-out request —
32	 * it DEBITS the wallet now and records a PENDING AffiliatePayout (admin later marks
33	 * PAID; a DECLINE credits the wallet back). Guards:
34	 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
35	 *  - amount ≤ the caller's cashable affiliate balance (unclaimed referral
36	 *    commission, capped by the actual wallet balance), re-read INSIDE the
37	 *    transaction so two concurrent requests can't both pass a stale check.
38	 *  - the wallet debit is an atomic guarded updateMany, so even a race can never
39	 *    drive the balance negative — the second request fails cleanly.
40	 */
41	export async function requestAffiliatePayout(
42	  amountCents: number
43	): Promise<{ ok?: boolean; error?: string }> {
44	  // Money path, and the sharpest one in the product: this converts a customer's
45	  // wallet balance into a CASH-OUT request that a member of staff then marks
46	  // PAID. An admin impersonating a customer could open the request and approve
47	  // it themselves, so the whole loop — request and approval — would sit with one
48	  // person and never involve the account holder at all. `adminUpdatePayout`
49	  // below is deliberately staff-gated for the second half; this is the first.
50	  await assertNotImpersonating();
51	  const user = await requireUser();
52	  // Purchase gate: an unverified address means we cannot reach the person we
53	  // are about to charge. See lib/email-verification.ts.
54	  const unverified = await emailVerificationError(user);
55	  if (unverified) return { error: unverified };
56	
57	  // Feature flag: the referral/affiliate program can be switched off platform-wide.
58	  if (!(await getSettingBool("feature_referrals", true))) {
59	    return { error: "The affiliate program is currently unavailable." };
60	  }
61	
62	  const cents = Math.round(Number(amountCents));
63	  if (!Number.isFinite(cents) || cents <= 0) {
64	    return { error: "Enter a valid amount." };
65	  }
66	  if (cents < MIN_PAYOUT_CENTS) {
67	    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
68	  }
69	
70	  try {
71	    await db.$transaction(async (tx) => {
72	      // Re-read all state inside the tx to serialize concurrent requests.
73	      const [account, earnedAgg, payouts] = await Promise.all([
74	        tx.user.findUnique({ where: { id: user.id }, select: { balanceCents: true } }),
75	        tx.walletTransaction.aggregate({
76	          _sum: { amountCents: true },
77	          where: { userId: user.id, description: REFERRAL_EARNING_DESCRIPTION },
78	        }),
79	        tx.affiliatePayout.findMany({
80	          where: { userId: user.id, status: { not: "DECLINED" } },
81	          select: { amountCents: true },
82	        }),
83	      ]);
84	      const walletBalanceCents = account?.balanceCents ?? 0;
85	      const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
86	      const claimedCents = payouts.reduce((s, p) => s + p.amountCents, 0);
87	      const availableCents = Math.max(
88	        0,
89	        Math.min(walletBalanceCents, totalEarnedCents - claimedCents)
90	      );
91	      if (cents > availableCents) throw new PayoutExceedsAvailableError(availableCents);
92	
93	      // Atomic guarded debit — hard-stops any residual race from overdrawing.
94	      await debitWallet(tx, user.id, cents);
95	      await tx.walletTransaction.create({
96	        data: {
97	          userId: user.id,
98	          amountCents: -cents,
99	          description: "Affiliate payout request (wallet cash-out)",
100	        },
101	      });
102	      await tx.affiliatePayout.create({
103	        data: { userId: user.id, amountCents: cents, status: "PENDING" },
104	      });
105	      await tx.auditLog.create({
106	        data: {
107	          userId: user.id,
108	          action: "affiliate.payout_request",
109	          detail: `$${(cents / 100).toFixed(2)}`,
110	        },
111	      });
112	    });
113	  } catch (e) {
114	    if (e instanceof PayoutExceedsAvailableError) {
115	      return { error: `You only have $${(e.availableCents / 100).toFixed(2)} available to withdraw.` };
116	    }
117	    if (e instanceof InsufficientBalanceError) {
118	      return { error: "Insufficient wallet balance for this payout." };
119	    }
120	    throw e;
121	  }
122	
123	  revalidatePath("/dashboard/affiliate");
124	  return { ok: true };
125	}
126	
127	// ---------- Admin: update a payout's status ----------
128	
129	const ALLOWED: readonly PayoutStatus[] = PAYOUT_STATUSES;
130	
131	/**
132	 * Move a payout request to APPROVED / PAID / DECLINED. Money already left the
133	 * wallet when the request was created, so:
134	 *   - PAID     : just stamp `paidAt` (no wallet change — cash was already reserved).
135	 *   - DECLINED : credit the reserved amount back to the wallet (cash-out cancelled).
136	 *   - reactivating a DECLINED payout (back to PENDING/APPROVED/PAID): re-debit it,
137	 *     guarded, so a declined-then-reinstated payout can't be double-spent.
138	 * Billing-area gated. The status change + wallet move are one transaction.
139	 */
140	export async function adminUpdatePayout(
141	  id: string,
142	  status: string
143	): Promise<{ ok?: boolean; error?: string }> {
144	  const admin = await requireArea("billing");
145	
146	  if (!ALLOWED.includes(status as PayoutStatus)) {
147	    return { error: "Invalid status." };
148	  }
149	  const payout = await db.affiliatePayout.findUnique({ where: { id } });
150	  if (!payout) return { error: "Payout not found." };
151	
152	  const wasDeclined = payout.status === "DECLINED";
153	  const willDecline = status === "DECLINED";
154	
155	  try {
156	    await db.$transaction(async (tx) => {
157	      await tx.affiliatePayout.update({
158	        where: { id },
159	        data: {
160	          status,
161	          paidAt: status === "PAID" ? new Date() : null,
162	        },
163	      });
164	      if (willDecline && !wasDeclined) {
165	        // Cancel the cash-out: return the reserved funds to the wallet.
166	        await tx.user.update({
167	          where: { id: payout.userId },
168	          data: { balanceCents: { increment: payout.amountCents } },
169	        });
170	        await tx.walletTransaction.create({
171	          data: {
172	            userId: payout.userId,
173	            amountCents: payout.amountCents,
174	            description: "Affiliate payout declined (funds returned)",
175	          },
176	        });
177	      } else if (!willDecline && wasDeclined) {
178	        // Reinstating a previously-declined payout: re-reserve the funds (guarded).
179	        await debitWallet(tx, payout.userId, payout.amountCents);
180	        await tx.walletTransaction.create({
181	          data: {
182	            userId: payout.userId,
183	            amountCents: -payout.amountCents,
184	            description: "Affiliate payout reinstated (wallet cash-out)",
185	          },
186	        });
187	      }
188	    });
189	  } catch (e) {
190	    if (e instanceof InsufficientBalanceError) {
191	      return { error: "Customer's wallet no longer covers this payout — cannot reinstate." };
192	    }
193	    throw e;
194	  }
195	
196	  await db.auditLog.create({
197	    data: {
198	      userId: admin.id,
199	      action: "affiliate.payout_update",
200	      detail: `${payout.id} → ${status} ($${(payout.amountCents / 100).toFixed(2)})`,
201	    },
202	  });
203	
204	  revalidatePath("/admin/affiliate");
205	  return { ok: true };
206	}
