152	/**
153	 * Detach a customer from a partner. Historical commission rows are LEFT INTACT
154	 * (they record charges that really happened); only the forward attachment is
155	 * removed, so no new commission accrues for this customer afterwards.
156	 */
157	export async function adminDetachCustomer(
158	  attachmentId: string
159	): Promise<{ error?: string; ok?: boolean }> {
160	  const admin = await requireArea("billing");
161	  const attachment = await db.partnerCustomer.findUnique({ where: { id: attachmentId } });
162	  if (!attachment) return { error: "Attachment not found." };
163	
164	  await db.partnerCustomer.delete({ where: { id: attachmentId } });
165	  await db.auditLog.create({
166	    data: {
167	      userId: admin.id,
168	      action: "partner.detach",
169	      detail: `${attachment.partnerId} -/- ${attachment.customerId}`,
170	    },
171	  });
172	  revalidatePath(`/admin/partners/${attachment.partnerId}`);
173	  return { ok: true };
174	}
