import type { Prisma } from "@prisma/client";
import { db } from "./db";

/**
 * Real net lifetime revenue for a customer — how much cash they have actually
 * ever handed Nxeon, net of refunds.
 *
 * REAL DEFECT this module fixes: `app/admin/users/[id]/page.tsx` computed
 * "Lifetime spend" as `SUM(Invoice.amountCents - Invoice.refundedCents)` over
 * every PAID invoice. That double-counts. Every real payment (Stripe/PayPal/
 * Coinbase) first CREDITS the wallet (`creditCheckoutSession` in lib/stripe.ts,
 * `creditExternalPayment` in lib/fulfil-checkout.ts) as a POSITIVE
 * `WalletTransaction` tagged with `stripeSessionId` (reused across all three
 * gateways). If the payment isn't immediately spent on a specific purchase
 * (`isPurchaseLegSession` is false), it ALSO writes a PAID "Wallet top-up"
 * Invoice documenting the cash arrived. Separately, EVERY spend — an order
 * (lib/order.ts), a renewal (worker/billing.ts commitRenewal), a resize, a
 * domain, etc. — DEBITS the wallet (a negative WalletTransaction, no
 * stripeSessionId) and ALSO writes its own PAID invoice for the thing bought,
 * regardless of whether the money spent was fresh or old wallet balance.
 *
 * Concrete example: a customer tops up $15 (Invoice "Wallet top-up", $15,
 * PAID) then later spends $8.88 of it on a VPS (Invoice "Order: … VPS …",
 * $8.88, PAID). Summing both invoices reports $23.88 of "lifetime spend" when
 * the customer only ever gave Nxeon $15. The WalletTransaction ledger is
 * correct throughout (+1500, then -888) — the bug is purely in deriving
 * "lifetime spend" from Invoice rows instead of from the ledger.
 *
 * The fix: count real cash IN once, at the moment it actually arrived — every
 * POSITIVE WalletTransaction carrying a `stripeSessionId` (see
 * `REAL_CASH_IN_WHERE`) — and subtract refunds via `Invoice.refundedCents`
 * (the authoritative "how much billed has been given back" figure; see that
 * field's own doc comment in schema.prisma). `stripeSessionId IS NOT NULL` is
 * exactly what separates a real payment from a free credit: referral bonuses
 * (lib/actions-growth.ts) and the admin "Credit" button
 * (lib/actions-admin-billing.ts `adjustBalance`) both write positive
 * WalletTransaction rows with NO `stripeSessionId`, so they are correctly
 * excluded here without needing a description-prefix allowlist.
 *
 * This is a DIFFERENT figure from the platform-wide "Revenue" shown on
 * /admin/billing, /admin/subscriptions, /admin/analytics and /admin/accounting
 * (see `REVENUE_WHERE` in lib/admin-metrics.ts). Those pages recognise revenue
 * when wallet balance is SPENT (a negative, non-reversal WalletTransaction) —
 * a revenue-recognition view that only counts a top-up once it's actually
 * consumed. This module instead answers "how much has this customer ever
 * really paid us", which is a cash-received view and must count a top-up the
 * moment it lands, whether or not it has been spent yet. Both are correct for
 * what they each claim to measure; do not merge them.
 *
 * Reporting/analytics only — this module never reads or writes money. It is
 * pure derivation over WalletTransaction/Invoice, which are the source of
 * truth written by lib/stripe.ts, lib/fulfil-checkout.ts, lib/order.ts,
 * worker/billing.ts and lib/actions-admin-billing.ts.
 */

/**
 * Prisma `where` fragment selecting the WalletTransaction rows that represent
 * real cash actually received: a positive amount carrying a `stripeSessionId`
 * (set by `creditCheckoutSession` / `creditExternalPayment` for every genuine
 * Stripe, PayPal or Coinbase payment, regardless of gateway). Free credits —
 * referral bonuses, admin balance adjustments — are positive too but never
 * carry a `stripeSessionId`, so this fragment excludes them without needing a
 * description allowlist.
 */
export const REAL_CASH_IN_WHERE: Prisma.WalletTransactionWhereInput = {
  amountCents: { gt: 0 },
  stripeSessionId: { not: null },
};

/**
 * Pure predicate mirroring `REAL_CASH_IN_WHERE`, for testing the classification
 * without a database. Kept in exact sync with the Prisma fragment above — both
 * express "a genuine payment landed", never anything derived from Invoice.
 */
export function countsAsRealCashIn(row: { amountCents: number; stripeSessionId: string | null }): boolean {
  return row.amountCents > 0 && row.stripeSessionId != null;
}

/**
 * Net a customer's real cash-in total against refunds already recorded
 * against their invoices. Pure arithmetic, split out from the DB-backed
 * functions below so the actual netting logic can be tested without a
 * database. Clamped at 0 — refunds should never exceed what was paid in, but
 * a display figure must never go negative even if bookkeeping drifts.
 */
export function netLifetimeSpendCents(cashInCents: number, refundedCents: number): number {
  return Math.max(0, cashInCents - refundedCents);
}

/**
 * Real net lifetime revenue for a single customer, in cents. See module doc
 * for the formula and why a naive Invoice sum overstates it.
 */
export async function realLifetimeSpendCents(userId: string): Promise<number> {
  const [paidIn, refunds] = await Promise.all([
    db.walletTransaction.aggregate({
      where: { ...REAL_CASH_IN_WHERE, userId },
      _sum: { amountCents: true },
    }),
    db.invoice.aggregate({
      where: { userId },
      _sum: { refundedCents: true },
    }),
  ]);
  return netLifetimeSpendCents(paidIn._sum.amountCents ?? 0, refunds._sum.refundedCents ?? 0);
}

/**
 * Batched version of `realLifetimeSpendCents` for admin list pages that need
 * this per-user across many customers at once — two `groupBy` queries instead
 * of N+1 per-user round trips. Mirrors the batching pattern in
 * `lib/retention.ts` (`signupRetentionRows`).
 *
 * Users with no real cash in and no refunds are simply absent from the
 * returned map (treat a missing key as 0), matching how `groupBy` naturally
 * omits users with no matching rows.
 */
export async function realLifetimeSpendCentsByUser(
  userIds: string[]
): Promise<Map<string, number>> {
  const result = new Map<string, number>();
  if (userIds.length === 0) return result;

  const [paidInRows, refundRows] = await Promise.all([
    db.walletTransaction.groupBy({
      by: ["userId"],
      where: { ...REAL_CASH_IN_WHERE, userId: { in: userIds } },
      _sum: { amountCents: true },
    }),
    db.invoice.groupBy({
      by: ["userId"],
      where: { userId: { in: userIds } },
      _sum: { refundedCents: true },
    }),
  ]);

  const cashInByUser = new Map<string, number>();
  for (const row of paidInRows) cashInByUser.set(row.userId, row._sum.amountCents ?? 0);
  const refundedByUser = new Map<string, number>();
  for (const row of refundRows) refundedByUser.set(row.userId, row._sum.refundedCents ?? 0);

  const ids = new Set([...cashInByUser.keys(), ...refundedByUser.keys()]);
  for (const id of ids) {
    result.set(id, netLifetimeSpendCents(cashInByUser.get(id) ?? 0, refundedByUser.get(id) ?? 0));
  }
  return result;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  REAL_CASH_IN_WHERE,
  countsAsRealCashIn,
  netLifetimeSpendCents,
} from "../lib/revenue.ts";

/**
 * "Lifetime spend" on /admin/users/[id] used to be `SUM(Invoice.amountCents -
 * Invoice.refundedCents)` over every PAID invoice. Every real payment credits
 * the wallet (WalletTransaction, positive, stripeSessionId set) and — when it
 * isn't immediately spent on something specific — ALSO writes a "Wallet
 * top-up" invoice. Every later spend debits the wallet AND writes its own
 * invoice for the thing bought. Summing both invoices double-counts money
 * that only ever entered the business once.
 *
 * These tests pin the fix: a customer's real lifetime spend is what actually
 * arrived in the wallet (a positive, stripeSessionId-tagged transaction), net
 * of refunds — never a sum of billing documents.
 */

test("REAL_CASH_IN_WHERE selects positive, stripeSessionId-tagged rows only", () => {
  assert.deepEqual(REAL_CASH_IN_WHERE.amountCents, { gt: 0 });
  assert.deepEqual(REAL_CASH_IN_WHERE.stripeSessionId, { not: null });
});

/* ================================================================== *
 * Row classification — mirrors every WalletTransaction-writing path
 * ================================================================== */

test("a real payment (Stripe/PayPal/Coinbase top-up) counts as cash in", () => {
  // creditCheckoutSession / creditExternalPayment: positive, stripeSessionId set
  // (the column is reused across all three gateways).
  assert.equal(countsAsRealCashIn({ amountCents: 1500, stripeSessionId: "cs_test_123" }), true);
  assert.equal(countsAsRealCashIn({ amountCents: 999, stripeSessionId: "PAYID-abc" }), true);
});

test("a spend debit never counts as cash in, regardless of stripeSessionId", () => {
  // lib/order.ts / worker/billing.ts commitRenewal: negative, no stripeSessionId.
  assert.equal(countsAsRealCashIn({ amountCents: -888, stripeSessionId: null }), false);
});

test("a referral bonus does NOT count as cash in", () => {
  // lib/actions-growth.ts maybeRewardReferral: positive, but never a real payment.
  assert.equal(countsAsRealCashIn({ amountCents: 500, stripeSessionId: null }), false);
});

test("an admin balance adjustment (the Credit button) does NOT count as cash in", () => {
  // lib/actions-admin-billing.ts adjustBalance: positive goodwill credit, no
  // stripeSessionId — must not inflate a customer's real lifetime spend.
  assert.equal(countsAsRealCashIn({ amountCents: 2000, stripeSessionId: null }), false);
});

/* ================================================================== *
 * Refund netting — pure arithmetic
 * ================================================================== */

test("a refund reduces lifetime spend, clamped at zero", () => {
  assert.equal(netLifetimeSpendCents(1500, 0), 1500);
  assert.equal(netLifetimeSpendCents(1500, 500), 1000);
  assert.equal(netLifetimeSpendCents(1500, 1500), 0);
  // Refunds should never exceed cash in, but a display figure must never go
  // negative even if bookkeeping drifts.
  assert.equal(netLifetimeSpendCents(1500, 2000), 0);
});

/* ================================================================== *
 * The exact incident: top up $15, spend $8.88 of it on a VPS
 * ================================================================== */

test("wallet-top-up-then-spend: lifetime spend is the top-up, not top-up + order", () => {
  const ledger = [
    // Real payment: $15.00 top-up.
    { amountCents: 1500, stripeSessionId: "cs_topup_1" },
    // Spending $8.88 of that same balance on a VPS order — a debit, no
    // stripeSessionId, and it also produced its own "Order: … VPS …" invoice
    // that the OLD code summed alongside the top-up invoice.
    { amountCents: -888, stripeSessionId: null },
  ];
  const cashInCents = ledger.filter(countsAsRealCashIn).reduce((s, r) => s + r.amountCents, 0);
  assert.equal(cashInCents, 1500, "only the top-up is real cash in — the spend is not a second payment");
  assert.equal(netLifetimeSpendCents(cashInCents, 0), 1500, "$15.00, not $23.88");
});

test("a referral credit later spent still never counts toward lifetime spend", () => {
  const ledger = [
    { amountCents: 800, stripeSessionId: null }, // referral bonus
    { amountCents: -800, stripeSessionId: null }, // spent on something
  ];
  const cashInCents = ledger.filter(countsAsRealCashIn).reduce((s, r) => s + r.amountCents, 0);
  assert.equal(cashInCents, 0, "free credit was never a real payment, spent or not");
});

test("a full refund of a top-up brings lifetime spend back to zero", () => {
  const ledger = [{ amountCents: 1500, stripeSessionId: "cs_topup_1" }];
  const cashInCents = ledger.filter(countsAsRealCashIn).reduce((s, r) => s + r.amountCents, 0);
  // Invoice.refundedCents on the "Wallet top-up" invoice records the $15 refund.
  assert.equal(netLifetimeSpendCents(cashInCents, 1500), 0);
});

